-- Checks the data generated by tools/gen_recipes.py (CrafterArbitrage/Data/*.lua) against recipes whose
-- values are known from the game.
return function()
    local CA = { Data = {} }
    local PROFESSIONS = { "Alchemy", "Blacksmithing", "Engineering", "Leatherworking", "Tailoring", "Cooking", "FirstAid", "Smelting" }
    for _, name in ipairs(PROFESSIONS) do
        assert(loadfile("CrafterArbitrage/Data/" .. name .. ".lua"))("CrafterArbitrage", CA)
    end
    assert(loadfile("CrafterArbitrage/Data/Items.lua"))("CrafterArbitrage", CA)
    assert(loadfile("CrafterArbitrage/Data/Trainers.lua"))("CrafterArbitrage", CA)

    describe("CrafterArbitrage data", function()
        it("has recipes for every profession", function()
            for _, name in ipairs(PROFESSIONS) do
                local n = 0
                for _ in pairs(CA.Data[name].recipes) do n = n + 1 end
                assert(n > 0, name .. " has no recipes")
            end
        end)

        it("reads Brown Linen Vest: one Bolt of Linen Cloth and one Coarse Thread", function()
            local r = CA.Data.Tailoring.recipes[2385]
            assertEqual(r.out, { 2568, 1 })
            assertEqual(r.r, { { 2996, 1 }, { 2320, 1 } })
            assertEqual({ r.orange, r.yellow, r.green, r.gray }, { 1, 57, 45, 70 })
        end)

        it("reads the quantity a recipe makes", function()
            assertEqual(CA.Data.Smelting.recipes[2659].out, { 2841, 2 }) -- Smelt Bronze makes 2 bars
            assertEqual(CA.Data.Cooking.recipes[2549].out, { 1017, 3 })
        end)

        it("has vendor prices for items", function()
            assertEqual(CA.Data.Items[2589].sell, 13) -- Linen Cloth
        end)

        it("says what a trainer charges and requires for a recipe", function()
            local r = CA.Data.Tailoring.recipes[2385]
            assertEqual(r.train, { 10, 45 }) -- skill 10, 45 copper
            assertEqual(CA.Data.Trainers[1103], { "Eldrin", "Journeyman Tailor", "A", 12, 79.22, 69.03 }) -- Alliance, Elwynn Forest
            local listed = false
            for _, npc in ipairs(r.trainers) do listed = listed or npc == 1103 end
            assert(listed, "Eldrin should teach Brown Linen Vest")
        end)

        it("lists at least one trainer for every recipe with a trainer price", function()
            for _, r in pairs(CA.Data.Tailoring.recipes) do
                assert(not r.train or #r.trainers > 0, "train without trainers")
            end
        end)

        it("says which faction each trainer serves", function()
            assertEqual(CA.Data.Trainers[3004][3], "H") -- Tepa
            for npc, t in pairs(CA.Data.Trainers) do
                assert(t[3] == "A" or t[3] == "H" or t[3] == "AH" or t[3] == "", "trainer " .. npc .. " has faction " .. tostring(t[3]))
            end
        end)

        it("lists the profession ranks with their price and skill", function()
            assertEqual(CA.Data.Tailoring.ranks, { { 1, 10, 0, 5 }, { 2, 450, 50, 10 }, { 3, 4500, 125, 20 }, { 4, 50000, 200, 0 } })
        end)

        it("gives every recipe an output quantity and reagents", function()
            for _, name in ipairs(PROFESSIONS) do
                for spell, r in pairs(CA.Data[name].recipes) do
                    assert(#r.r > 0 or r.acq, name .. " recipe " .. spell .. " has no reagents")
                    assert(r.out[2] >= 1, name .. " recipe " .. spell .. " makes nothing")
                end
            end
        end)
    end)
end
